from __future__ import annotations

from dataclasses import dataclass
from typing import Dict, Tuple

from rules.types import TerrainType


TerrainPalette = Dict[TerrainType, Tuple[int, int, int]]


DEFAULT_TERRAIN_PALETTE: TerrainPalette = {
    TerrainType.FOREST: (65, 120, 70),
    TerrainType.MOUNTAIN: (125, 125, 125),
    TerrainType.WATER: (70, 110, 170),
    TerrainType.DESERT: (185, 165, 95),
    TerrainType.SWAMP: (120, 85, 130),
}


@dataclass(frozen=True, slots=True)
class TerrainPrediction:
    terrain: TerrainType
    distance: float
    confidence: float


def _distance(a: Tuple[int, int, int], b: Tuple[int, int, int]) -> float:
    return ((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2 + (a[2] - b[2]) ** 2) ** 0.5


def normalize_rgb(rgb_mean: Tuple[int, int, int], target_luminance: float = 128.0) -> Tuple[int, int, int]:
    r, g, b = rgb_mean
    luminance = (r + g + b) / 3.0
    if luminance <= 1e-6:
        return rgb_mean
    scale = target_luminance / luminance
    return (
        int(max(0, min(255, round(r * scale)))),
        int(max(0, min(255, round(g * scale)))),
        int(max(0, min(255, round(b * scale)))),
    )


def classify_terrain_with_confidence(
    rgb_mean: Tuple[int, int, int],
    palette: TerrainPalette | None = None,
    normalize_input: bool = False,
) -> TerrainPrediction:
    palette = palette or DEFAULT_TERRAIN_PALETTE
    sample_rgb = normalize_rgb(rgb_mean) if normalize_input else rgb_mean

    ranked = []
    for terrain, terrain_rgb in palette.items():
        reference_rgb = normalize_rgb(terrain_rgb) if normalize_input else terrain_rgb
        ranked.append((terrain, _distance(sample_rgb, reference_rgb)))
    ranked.sort(key=lambda item: item[1])

    best_terrain, best_distance = ranked[0]
    denominator = sum(1.0 / (distance + 1e-6) for _, distance in ranked)
    confidence = (1.0 / (best_distance + 1e-6)) / denominator
    return TerrainPrediction(terrain=best_terrain, distance=best_distance, confidence=confidence)


def classify_terrain(
    rgb_mean: Tuple[int, int, int],
    palette: TerrainPalette | None = None,
    normalize_input: bool = False,
) -> TerrainType:
    return classify_terrain_with_confidence(
        rgb_mean=rgb_mean,
        palette=palette,
        normalize_input=normalize_input,
    ).terrain

from __future__ import annotations

from dataclasses import dataclass
from typing import Dict, Tuple

from game_model.types import TerrainType


TerrainPalette = Dict[TerrainType, Tuple[int, int, int]]


DEFAULT_TERRAIN_PALETTE: TerrainPalette = {
    TerrainType.FOREST: (65, 120, 70),
    TerrainType.MOUNTAIN: (125, 125, 125),
    TerrainType.WATER: (70, 110, 170),
    TerrainType.DESERT: (185, 165, 95),
    TerrainType.SWAMP: (120, 85, 130),
}


@dataclass(frozen=True, slots=True)
class TerrainPrediction:
    terrain: TerrainType
    distance: float
    confidence: float


def _distance(a: Tuple[int, int, int], b: Tuple[int, int, int]) -> float:
    return ((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2 + (a[2] - b[2]) ** 2) ** 0.5


def normalize_rgb(rgb_mean: Tuple[int, int, int], target_luminance: float = 128.0) -> Tuple[int, int, int]:
    r, g, b = rgb_mean
    luminance = (r + g + b) / 3.0
    if luminance <= 1e-6:
        return rgb_mean
    scale = target_luminance / luminance
    return (
        int(max(0, min(255, round(r * scale)))),
        int(max(0, min(255, round(g * scale)))),
        int(max(0, min(255, round(b * scale)))),
    )


def classify_terrain_with_confidence(
    rgb_mean: Tuple[int, int, int],
    palette: TerrainPalette | None = None,
    normalize_input: bool = False,
) -> TerrainPrediction:
    palette = palette or DEFAULT_TERRAIN_PALETTE
    sample_rgb = normalize_rgb(rgb_mean) if normalize_input else rgb_mean

    ranked = []
    for terrain, terrain_rgb in palette.items():
        reference_rgb = normalize_rgb(terrain_rgb) if normalize_input else terrain_rgb
        ranked.append((terrain, _distance(sample_rgb, reference_rgb)))
    ranked.sort(key=lambda item: item[1])

    best_terrain, best_distance = ranked[0]
    denominator = sum(1.0 / (distance + 1e-6) for _, distance in ranked)
    confidence = (1.0 / (best_distance + 1e-6)) / denominator
    return TerrainPrediction(terrain=best_terrain, distance=best_distance, confidence=confidence)


def classify_terrain(
    rgb_mean: Tuple[int, int, int],
    palette: TerrainPalette | None = None,
    normalize_input: bool = False,
) -> TerrainType:
    return classify_terrain_with_confidence(
        rgb_mean=rgb_mean,
        palette=palette,
        normalize_input=normalize_input,
    ).terrain

from collections import Counter
import json
from pathlib import Path

from data.board_loader import load_default_board, load_module_templates
from rules.tokens import GameState
from rules.types import StructureType, TokenType


def test_default_board_has_108_tiles() -> None:
    board = load_default_board()
    assert len(board.tiles) == 108


def test_each_section_has_18_tiles() -> None:
    board = load_default_board()
    section_counts = Counter(tile.section_id for tile in board.tiles.values())
    assert section_counts == {"A": 18, "B": 18, "C": 18, "D": 18, "E": 18, "F": 18}


def test_templates_define_two_orientations_with_18_tiles_each() -> None:
    templates = load_module_templates()
    for section_id, orientations in templates.items():
        assert set(orientations.keys()) == {"normal", "flipped"}
        assert len(orientations["normal"]) == 18
        assert len(orientations["flipped"]) == 18
        assert section_id in {"A", "B", "C", "D", "E", "F"}


def test_module_template_file_has_no_structures() -> None:
    path = Path("data/module_templates.json")
    payload = json.loads(path.read_text(encoding="utf-8"))
    for module in payload["modules"]:
        for orientation in ("normal", "flipped"):
            assert "structures" not in module["orientations"][orientation]


def test_structures_come_from_layout_instance() -> None:
    board = load_default_board()
    structure_tiles = [tile for tile in board.tiles.values() if tile.structure_type is not None]
    assert len(structure_tiles) == 6
    by_type = Counter(tile.structure_type for tile in structure_tiles)
    assert by_type[StructureType.STANDING_STONE] == 3
    assert by_type[StructureType.ABANDONED_SHACK] == 3


def test_center_tile_has_six_neighbors() -> None:
    board = load_default_board()
    neighbors = board.neighbors(8, 3)
    assert len(neighbors) == 6


def test_neighbor_rule_matches_documented_offsets() -> None:
    board = load_default_board()
    origin = (8, 3)
    expected = {
        (7, 3),   # left same row
        (9, 3),   # right same row
        (8, 2),   # above same column
        (8, 4),   # below same column
        (7, 2),   # upper-left
        (9, 2),   # upper-right
    }
    actual = {tile.coord for tile in board.neighbors(*origin)}
    assert actual == expected


def test_token_placement_updates_counts() -> None:
    board = load_default_board()
    state = GameState(board=board)
    state.place_token("p1", 1, 1, TokenType.ROUND)
    state.place_token("p2", 1, 1, TokenType.CUBE)
    assert state.token_counts() == {"round": 1, "cube": 1}

